1	// Package settings provides configuration loading for Entire.
2	// This package is separate from cli to allow strategy package to import it
3	// without creating an import cycle (cli imports strategy).
4	package settings
5	
6	import (
7		"bytes"
8		"context"
9		"encoding/json"
10		"fmt"
11		"os"
12		"path/filepath"
13		"strings"
14	
15		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
16		"github.com/entireio/cli/cmd/entire/cli/paths"
17	)
18	
19	const (
20		// EntireSettingsFile is the path to the Entire settings file
21		EntireSettingsFile = ".entire/settings.json"
22		// EntireSettingsLocalFile is the path to the local settings override file (not committed)
23		EntireSettingsLocalFile = ".entire/settings.local.json"
24	)
25	
26	// Commit linking mode constants.
27	const (
28		// CommitLinkingAlways auto-links commits to sessions without prompting.
29		CommitLinkingAlways = "always"
30		// CommitLinkingPrompt prompts the user on each commit (default for existing users).
31		CommitLinkingPrompt = "prompt"
32	)
33	
34	// EntireSettings represents the .entire/settings.json configuration
35	type EntireSettings struct {
36	
37		// Enabled indicates whether Entire is active. When false, CLI commands
38		// show a disabled message and hooks exit silently. Defaults to true.
39		Enabled bool `json:"enabled"`
40	
41		// LocalDev indicates whether to use "go run" instead of the "entire" binary
42		// This is used for development when the binary is not installed
43		LocalDev bool `json:"local_dev,omitempty"`
44	
45		// LogLevel sets the logging verbosity (debug, info, warn, error).
46		// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
47		// Defaults to "info".
48		LogLevel string `json:"log_level,omitempty"`
49	
50		// StrategyOptions contains strategy-specific configuration
51		StrategyOptions map[string]any `json:"strategy_options,omitempty"`
52	
53		// AbsoluteGitHookPath embeds the full binary path in git hooks instead of
54		// bare "entire". This is needed for GUI git clients (Xcode, Tower, etc.)
55		// that don't source shell profiles and can't find "entire" on PATH.
56		AbsoluteGitHookPath bool `json:"absolute_git_hook_path,omitempty"`
57	
58		// Telemetry controls anonymous usage analytics.
59		// nil = not asked yet (show prompt), true = opted in, false = opted out
60		Telemetry *bool `json:"telemetry,omitempty"`
61	
62		// Redaction configures PII redaction behavior for transcripts and metadata.
63		Redaction *RedactionSettings `json:"redaction,omitempty"`
64	
65		// CommitLinking controls how commits are linked to agent sessions.
66		// "always" = auto-link without prompting, "prompt" = ask on each commit.
67		// Defaults to "prompt" (preserves existing user behavior).
68		CommitLinking string `json:"commit_linking,omitempty"`
69	
70		// ExternalAgents enables discovery and registration of external agent
71		// plugins (entire-agent-* binaries on $PATH). Defaults to false.
72		ExternalAgents bool `json:"external_agents,omitempty"`
73	
74		// Deprecated: no longer used. Exists to tolerate old settings files
75		// that still contain "strategy": "auto-commit" or similar.
76		Strategy string `json:"strategy,omitempty"`
77	}
78	
79	// RedactionSettings configures redaction behavior beyond the default secret detection.
80	type RedactionSettings struct {
81		PII *PIISettings `json:"pii,omitempty"`
82	}
83	
84	// PIISettings configures PII detection categories.
85	// When Enabled is true, email and phone default to true; address defaults to false.
86	type PIISettings struct {
87		Enabled        bool              `json:"enabled"`
88		Email          *bool             `json:"email,omitempty"`
89		Phone          *bool             `json:"phone,omitempty"`
90		Address        *bool             `json:"address,omitempty"`
91		CustomPatterns map[string]string `json:"custom_patterns,omitempty"`
92	}
93	
94	// GetCommitLinking returns the effective commit linking mode.
95	// Returns the explicit value if set, otherwise defaults to "prompt"
96	// to preserve existing user behavior.
97	func (s *EntireSettings) GetCommitLinking() string {
98		if s.CommitLinking != "" {
99			return s.CommitLinking
100		}
101		return CommitLinkingPrompt
102	}
103	
104	// Load loads the Entire settings from .entire/settings.json,
105	// then applies any overrides from .entire/settings.local.json if it exists.
106	// Returns default settings if neither file exists.
107	// Works correctly from any subdirectory within the repository.
108	func Load(ctx context.Context) (*EntireSettings, error) {
109		// Get absolute paths for settings files
110		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
111		if err != nil {
112			settingsFileAbs = EntireSettingsFile // Fallback to relative
113		}
114		localSettingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
115		if err != nil {
116			localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
117		}
118	
119		// Load base settings
120		settings, err := loadFromFile(settingsFileAbs)
121		if err != nil {
122			return nil, fmt.Errorf("reading settings file: %w", err)
123		}
124	
125		// Apply local overrides if they exist
126		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
127		if err != nil {
128			if !os.IsNotExist(err) {
129				return nil, fmt.Errorf("reading local settings file: %w", err)
130			}
131			// Local file doesn't exist, continue without overrides
132		} else {
133			if err := mergeJSON(settings, localData); err != nil {
134				return nil, fmt.Errorf("merging local settings: %w", err)
135			}
136		}
137	
138		return settings, nil
139	}
140	
141	// LoadFromFile loads settings from a specific file path without merging local overrides.
142	// Returns default settings if the file doesn't exist.
143	// Use this when you need to display individual settings files separately.
144	func LoadFromFile(filePath string) (*EntireSettings, error) {
145		return loadFromFile(filePath)
146	}
147	
148	// LoadFromBytes parses settings from raw JSON bytes without merging local overrides.
149	// Use this when you have settings content from a non-file source (e.g., git show).
150	func LoadFromBytes(data []byte) (*EntireSettings, error) {
151		s := &EntireSettings{Enabled: true}
152		dec := json.NewDecoder(bytes.NewReader(data))
153		dec.DisallowUnknownFields()
154		if err := dec.Decode(s); err != nil {
155			return nil, fmt.Errorf("parsing settings: %w", err)
156		}
157		return s, nil
158	}
159	
160	// loadFromFile loads settings from a specific file path.
161	// Returns default settings if the file doesn't exist.
162	func loadFromFile(filePath string) (*EntireSettings, error) {
163		settings := &EntireSettings{
164			Enabled: true, // Default to enabled
165		}
166	
167		data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
168		if err != nil {
169			if os.IsNotExist(err) {
170				return settings, nil
171			}
172			return nil, fmt.Errorf("%w", err)
173		}
174	
175		dec := json.NewDecoder(bytes.NewReader(data))
176		dec.DisallowUnknownFields()
177		if err := dec.Decode(settings); err != nil {
178			return nil, fmt.Errorf("parsing settings file: %w", err)
179		}
180	
181		// Validate commit_linking if set
182		if settings.CommitLinking != "" && settings.CommitLinking != CommitLinkingAlways && settings.CommitLinking != CommitLinkingPrompt {
183			return nil, fmt.Errorf("invalid commit_linking value %q: must be %q or %q", settings.CommitLinking, CommitLinkingAlways, CommitLinkingPrompt)
184		}
185	
186		return settings, nil
187	}
188	
189	// mergeJSON merges JSON data into existing settings.
190	// Only non-zero values from the JSON override existing settings.
191	func mergeJSON(settings *EntireSettings, data []byte) error {
192		// First, validate that there are no unknown keys using strict decoding
193		dec := json.NewDecoder(bytes.NewReader(data))
194		dec.DisallowUnknownFields()
195		var temp EntireSettings
196		if err := dec.Decode(&temp); err != nil {
197			return fmt.Errorf("parsing JSON: %w", err)
198		}
199	
200		// Parse into a map to check which fields are present
201		var raw map[string]json.RawMessage
202		if err := json.Unmarshal(data, &raw); err != nil {
203			return fmt.Errorf("parsing JSON: %w", err)
204		}
205	
206		// Override enabled if present
207		if enabledRaw, ok := raw["enabled"]; ok {
208			var e bool
209			if err := json.Unmarshal(enabledRaw, &e); err != nil {
210				return fmt.Errorf("parsing enabled field: %w", err)
211			}
212			settings.Enabled = e
213		}
214	
215		// Override local_dev if present
216		if localDevRaw, ok := raw["local_dev"]; ok {
217			var ld bool
218			if err := json.Unmarshal(localDevRaw, &ld); err != nil {
219				return fmt.Errorf("parsing local_dev field: %w", err)
220			}
221			settings.LocalDev = ld
222		}
223	
224		// Override absolute_git_hook_path if present
225		if ahpRaw, ok := raw["absolute_git_hook_path"]; ok {
226			var ahp bool
227			if err := json.Unmarshal(ahpRaw, &ahp); err != nil {
228				return fmt.Errorf("parsing absolute_git_hook_path field: %w", err)
229			}
230			settings.AbsoluteGitHookPath = ahp
231		}
232	
233		// Override log_level if present and non-empty
234		if logLevelRaw, ok := raw["log_level"]; ok {
235			var ll string
236			if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
237				return fmt.Errorf("parsing log_level field: %w", err)
238			}
239			if ll != "" {
240				settings.LogLevel = ll
241			}
242		}
243	
244		// Merge strategy_options if present
245		if optionsRaw, ok := raw["strategy_options"]; ok {
246			var opts map[string]any
247			if err := json.Unmarshal(optionsRaw, &opts); err != nil {
248				return fmt.Errorf("parsing strategy_options field: %w", err)
249			}
250			if settings.StrategyOptions == nil {
251				settings.StrategyOptions = opts
252			} else {
253				for k, v := range opts {
254					settings.StrategyOptions[k] = v
255				}
256			}
257		}
258	
259		// Override telemetry if present
260		if telemetryRaw, ok := raw["telemetry"]; ok {
261			var t bool
262			if err := json.Unmarshal(telemetryRaw, &t); err != nil {
263				return fmt.Errorf("parsing telemetry field: %w", err)
264			}
265			settings.Telemetry = &t
266		}
267	
268		// Merge redaction sub-fields if present (field-level, not wholesale replace).
269		if redactionRaw, ok := raw["redaction"]; ok {
270			if settings.Redaction == nil {
271				settings.Redaction = &RedactionSettings{}
272			}
273			if err := mergeRedaction(settings.Redaction, redactionRaw); err != nil {
274				return fmt.Errorf("parsing redaction field: %w", err)
275			}
276		}
277	
278		// Override commit_linking if present and non-empty
279		if commitLinkingRaw, ok := raw["commit_linking"]; ok {
280			var cl string
281			if err := json.Unmarshal(commitLinkingRaw, &cl); err != nil {
282				return fmt.Errorf("parsing commit_linking field: %w", err)
283			}
284			if cl != "" {
285				switch cl {
286				case CommitLinkingAlways, CommitLinkingPrompt:
287					settings.CommitLinking = cl
288				default:
289					return fmt.Errorf("invalid commit_linking value %q: must be %q or %q", cl, CommitLinkingAlways, CommitLinkingPrompt)
290				}
291			}
292		}
293	
294		// Override external_agents if present
295		if externalAgentsRaw, ok := raw["external_agents"]; ok {
296			var ea bool
297			if err := json.Unmarshal(externalAgentsRaw, &ea); err != nil {
298				return fmt.Errorf("parsing external_agents field: %w", err)
299			}
300			settings.ExternalAgents = ea
301		}
302	
303		return nil
304	}
305	
306	// mergeRedaction merges redaction overrides into existing RedactionSettings.
307	// Only fields present in the override JSON are applied.
308	func mergeRedaction(dst *RedactionSettings, data json.RawMessage) error {
309		var raw map[string]json.RawMessage
310		if err := json.Unmarshal(data, &raw); err != nil {
311			return fmt.Errorf("parsing redaction: %w", err)
312		}
313		if piiRaw, ok := raw["pii"]; ok {
314			if dst.PII == nil {
315				dst.PII = &PIISettings{}
316			}
317			if err := mergePIISettings(dst.PII, piiRaw); err != nil {
318				return err
319			}
320		}
321		return nil
322	}
323	
324	// mergePIISettings merges PII overrides into existing PIISettings.
325	// Only fields present in the override JSON are applied; missing fields
326	// are preserved from the base settings.
327	func mergePIISettings(dst *PIISettings, data json.RawMessage) error {
328		var raw map[string]json.RawMessage
329		if err := json.Unmarshal(data, &raw); err != nil {
330			return fmt.Errorf("parsing pii: %w", err)
331		}
332		if v, ok := raw["enabled"]; ok {
333			if err := json.Unmarshal(v, &dst.Enabled); err != nil {
334				return fmt.Errorf("parsing pii.enabled: %w", err)
335			}
336		}
337		if v, ok := raw["email"]; ok {
338			var b bool
339			if err := json.Unmarshal(v, &b); err != nil {
340				return fmt.Errorf("parsing pii.email: %w", err)
341			}
342			dst.Email = &b
343		}
344		if v, ok := raw["phone"]; ok {
345			var b bool
346			if err := json.Unmarshal(v, &b); err != nil {
347				return fmt.Errorf("parsing pii.phone: %w", err)
348			}
349			dst.Phone = &b
350		}
351		if v, ok := raw["address"]; ok {
352			var b bool
353			if err := json.Unmarshal(v, &b); err != nil {
354				return fmt.Errorf("parsing pii.address: %w", err)
355			}
356			dst.Address = &b
357		}
358		if v, ok := raw["custom_patterns"]; ok {
359			var cp map[string]string
360			if err := json.Unmarshal(v, &cp); err != nil {
361				return fmt.Errorf("parsing pii.custom_patterns: %w", err)
362			}
363			if dst.CustomPatterns == nil {
364				dst.CustomPatterns = cp
365			} else {
366				for k, val := range cp {
367					dst.CustomPatterns[k] = val
368				}
369			}
370		}
371		return nil
372	}
373	
374	// IsSetUp returns true if Entire has been set up in the current repository.
375	// This checks if .entire/settings.json exists.
376	// Use this to avoid creating files/directories in repos where Entire was never enabled.
377	func IsSetUp(ctx context.Context) bool {
378		settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
379		if err != nil {
380			return false
381		}
382		_, err = os.Stat(settingsFileAbs)
383		return err == nil
384	}
385	
386	// IsSetUpAny returns true if Entire has been set up in the current repository,
387	// checking both .entire/settings.json and .entire/settings.local.json.
388	// Use this to detect any prior setup, even if only local settings exist.
389	func IsSetUpAny(ctx context.Context) bool {
390		if IsSetUp(ctx) {
391			return true
392		}
393		localFileAbs, err := paths.AbsPath(ctx, EntireSettingsLocalFile)
394		if err != nil {
395			return false
396		}
397		_, err = os.Lstat(localFileAbs)
398		return err == nil
399	}
400	
401	// IsSetUpAndEnabled returns true if Entire is both set up and enabled.
402	// This checks if .entire/settings.json exists AND has enabled: true.
403	// Use this for hooks that should be no-ops when Entire is not active.
404	func IsSetUpAndEnabled(ctx context.Context) bool {
405		if !IsSetUp(ctx) {
406			return false
407		}
408		s, err := Load(ctx)
409		if err != nil {
410			return false
411		}
412		return s.Enabled
413	}
414	
415	// IsCheckpointsV2Enabled checks if checkpoints v2 is enabled in settings.
416	// Returns false by default if settings cannot be loaded or the key is missing.
417	func IsCheckpointsV2Enabled(ctx context.Context) bool {
418		settings, err := Load(ctx)
419		if err != nil {
420			return false
421		}
422		return settings.IsCheckpointsV2Enabled()
423	}
424	
425	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled in settings.
426	// Returns false by default if settings cannot be loaded or flags are missing.
427	func IsPushV2RefsEnabled(ctx context.Context) bool {
428		s, err := Load(ctx)
429		if err != nil {
430			return false
431		}
432		return s.IsPushV2RefsEnabled()
433	}
434	
435	// IsFilteredFetchesEnabled checks if filtered fetches should be used.
436	// When enabled, filtered fetches always resolve remote names to URLs first so
437	// git does not persist promisor settings onto named remotes in local config.
438	// Returns false by default.
439	func IsFilteredFetchesEnabled(ctx context.Context) bool {
440		s, err := Load(ctx)
441		if err != nil {
442			return false
443		}
444		return s.IsFilteredFetchesEnabled()
445	}
446	
447	// IsSummarizeEnabled checks if auto-summarize is enabled in settings.
448	// Returns false by default if settings cannot be loaded or the key is missing.
449	func IsSummarizeEnabled(ctx context.Context) bool {
450		settings, err := Load(ctx)
451		if err != nil {
452			return false
453		}
454		return settings.IsSummarizeEnabled()
455	}
456	
457	// IsSummarizeEnabled checks if auto-summarize is enabled in this settings instance.
458	func (s *EntireSettings) IsSummarizeEnabled() bool {
459		if s.StrategyOptions == nil {
460			return false
461		}
462		summarizeOpts, ok := s.StrategyOptions["summarize"].(map[string]any)
463		if !ok {
464			return false
465		}
466		enabled, ok := summarizeOpts["enabled"].(bool)
467		if !ok {
468			return false
469		}
470		return enabled
471	}
472	
473	// CheckpointRemoteConfig holds the structured checkpoint remote configuration.
474	// Stored in strategy_options.checkpoint_remote as {"provider": "github", "repo": "org/repo"}.
475	type CheckpointRemoteConfig struct {
476		Provider string // e.g., "github"
477		Repo     string // e.g., "org/checkpoints-repo"
478	}
479	
480	// Owner returns the owner portion of the repo field (before the slash).
481	// Returns empty string if the repo field doesn't contain a slash.
482	func (c *CheckpointRemoteConfig) Owner() string {
483		parts := strings.SplitN(c.Repo, "/", 2)
484		if len(parts) < 2 {
485			return ""
486		}
487		return parts[0]
488	}
489	
490	// GetCheckpointRemote returns the configured checkpoint remote.
491	// Expects a structured object: {"provider": "github", "repo": "org/repo"}.
492	// Returns nil if not configured, wrong type, or missing required fields.
493	func (s *EntireSettings) GetCheckpointRemote() *CheckpointRemoteConfig {
494		if s.StrategyOptions == nil {
495			return nil
496		}
497		val, ok := s.StrategyOptions["checkpoint_remote"]
498		if !ok {
499			return nil
500		}
501		m, ok := val.(map[string]any)
502		if !ok {
503			return nil
504		}
505		provider, providerOK := m["provider"].(string)
506		repo, repoOK := m["repo"].(string)
507		if !providerOK || !repoOK || provider == "" || repo == "" {
508			return nil
509		}
510		if !strings.Contains(repo, "/") {
511			return nil
512		}
513		return &CheckpointRemoteConfig{Provider: provider, Repo: repo}
514	}
515	
516	// IsCheckpointsV2Enabled checks if checkpoints v2 (dual-write to refs/entire/) is enabled.
517	// Returns false by default if the key is missing or not a bool.
518	func (s *EntireSettings) IsCheckpointsV2Enabled() bool {
519		if s.StrategyOptions == nil {
520			return false
521		}
522		val, ok := s.StrategyOptions["checkpoints_v2"].(bool)
523		return ok && val
524	}
525	
526	// IsPushV2RefsEnabled checks if pushing v2 refs is enabled.
527	// Requires both checkpoints_v2 and push_v2_refs to be true.
528	func (s *EntireSettings) IsPushV2RefsEnabled() bool {
529		if !s.IsCheckpointsV2Enabled() {
530			return false
531		}
532		if s.StrategyOptions == nil {
533			return false
534		}
535		val, ok := s.StrategyOptions["push_v2_refs"].(bool)
536		return ok && val
537	}
538	
539	// IsFilteredFetchesEnabled checks if fetches should use --filter=blob:none.
540	// When enabled, filtered fetches always use resolved URLs rather than remote
541	// names to avoid persisting promisor settings onto named remotes.
542	func (s *EntireSettings) IsFilteredFetchesEnabled() bool {
543		if s.StrategyOptions == nil {
544			return false
545		}
546		val, ok := s.StrategyOptions["filtered_fetches"].(bool)
547		return ok && val
548	}
549	
550	// IsPushSessionsDisabled checks if push_sessions is disabled in settings.
551	// Returns true if push_sessions is explicitly set to false.
552	func (s *EntireSettings) IsPushSessionsDisabled() bool {
553		if s.StrategyOptions == nil {
554			return false
555		}
556		val, exists := s.StrategyOptions["push_sessions"]
557		if !exists {
558			return false
559		}
560		if boolVal, ok := val.(bool); ok {
561			return !boolVal // disabled = !push_sessions
562		}
563		return false
564	}
565	
566	// IsExternalAgentsEnabled checks if external agent discovery is enabled in settings.
