		s.repo, rootTreeHash,
		[]string{shard, suffix},
		trailEntries,
		checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.ReplaceAll},
	)
	if err != nil {
		return fmt.Errorf("failed to update subtree: %w", err)
	}

